contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool asOwner, uint amount) public payable {
        require(amount > 0);

        uint balBefore = address(c).balance;

        if (asOwner) {
            // Owner-call path: fund c so that withdrawAll can succeed if amount is sufficient.
            require(address(this).balance >= amount);
            (bool sent, ) = address(c).call{value: amount}("");
            require(sent);

            bool reverted;
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }

            if (amount >= balBefore + amount) {
                assert(!reverted);
                assert(address(c).balance == 0);
            } else {
                assert(reverted);
                assert(address(c).balance == balBefore + amount);
            }
        } else {
            // Non-owner path: withdrawAll must revert and c's balance must not change.
            bool reverted;
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }

            assert(reverted);
            assert(address(c).balance == balBefore);
        }
    }

    receive() external payable {}

    fallback() external payable {}
}

