contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    receive() external payable {}

    function run(uint amount) public payable {
        // ensure the test contract is the owner (it deployed c)
        require(msg.sender == c.owner());
        uint beforeBal = address(c).balance;
        uint beforeSelf = address(this).balance;
        bool reverted;
        try c.withdraw(amount) { reverted = false; } catch { reverted = true; }
        // rule: revert iff amount > beforeBal; on success c loses exactly amount and caller gains exactly amount
        assert(reverted == (amount > beforeBal) &&
               (reverted ? address(c).balance == beforeBal && address(this).balance == beforeSelf
                         : address(c).balance == beforeBal - amount && address(this).balance == beforeSelf + amount));
    }
}

