        uint beforeDeposits = c.depositsCount();

        bool reverted = false;
        try c.sendMoney(target, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = cAddr.balance;
        uint afterDeposits = c.depositsCount();

        assert(
            (reverted && afterBalance == beforeBalance && afterDeposits == beforeDeposits) ||
            (!reverted &&
                (
                    (target == cAddr &&
                        ((afterBalance == beforeBalance && afterDeposits == beforeDeposits + 1) ||
                         (afterBalance + value == beforeBalance && afterDeposits == beforeDeposits))) ||
                    (target != cAddr &&
                        ((afterBalance == beforeBalance && afterDeposits == beforeDeposits) ||
                         (afterBalance + value == beforeBalance && afterDeposits == beforeDeposits)))
                ))
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(address target, uint value) public payable {
        require(address(this).balance >= value, "not enough balance");

        address cAddr = address(c);
        uint beforeBalance = cAddr.balance;
        uint beforeDeposits = c.depositsCount();

        c.sendMoney(target, value);

        uint afterBalance = cAddr.balance;
        uint afterDeposits = c.depositsCount();

        assert(
            (afterBalance + value == beforeBalance && afterDeposits == beforeDeposits) ||
            (afterBalance == beforeBalance &&
                ((target == cAddr && afterDeposits == beforeDeposits + 1) ||
                 (target != cAddr && afterDeposits == beforeDeposits)))
        );
    }
}
